solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <deque>
#include <optional>
#include <utility>

class PositionHistory
{
public:
    explicit PositionHistory(std::size_t capacity) : capacity_{ capacity } {}

    void record(std::int64_t tick, double x, double y)
    {
        if (!entries_.empty() && tick <= entries_.back().tick) return;
        entries_.push_back({ tick, x, y });
        while (entries_.size() > capacity_) entries_.pop_front();
    }

    std::optional<std::pair<double, double>> at(double tick) const
    {
        if (entries_.empty()) return std::nullopt;
        if (tick < static_cast<double>(entries_.front().tick) || tick > static_cast<double>(entries_.back().tick))
            return std::nullopt;
        for (std::size_t i{ 0 }; i < entries_.size(); ++i)
        {
            const Entry& b{ entries_[i] };
            if (tick > static_cast<double>(b.tick)) continue;
            if (i == 0 || tick == static_cast<double>(b.tick)) return std::pair{ b.x, b.y };
            const Entry& a{ entries_[i - 1] };
            const double f{ (tick - static_cast<double>(a.tick)) / static_cast<double>(b.tick - a.tick) };
            return std::pair{ a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f };
        }
        return std::nullopt;
    }

private:
    struct Entry { std::int64_t tick; double x; double y; };
    std::size_t capacity_;
    std::deque<Entry> entries_;
};

double rewindTick(double claimed, std::int64_t now, int maxRewind)
{
    return std::clamp(claimed, static_cast<double>(now - maxRewind), static_cast<double>(now));
}

bool segmentHitsCircle(double ox, double oy, double dx, double dy, double range,
                       double cx, double cy, double radius)
{
    const double length{ std::hypot(dx, dy) };
    if (length == 0) return false;
    const double ux{ dx / length };
    const double uy{ dy / length };
    const double along{ std::clamp((cx - ox) * ux + (cy - oy) * uy, 0.0, range) };
    const double px{ ox + ux * along - cx };
    const double py{ oy + uy * along - cy };
    return px * px + py * py <= radius * radius;
}

unitTests:
TEST("a history of positions") {
    PositionHistory h{ 4 };
    CHECK(!h.at(0).has_value());
    for (std::int64_t t{ 10 }; t <= 15; ++t) h.record(t, t * 10.0, 1.0);
    CHECK(!h.at(11).has_value());
    const auto a{ h.at(13.5) };
    CHECK(a.has_value() && std::abs(a->first - 135) < 1e-9 && std::abs(a->second - 1) < 1e-9);
    const auto b{ h.at(12) };
    CHECK(b.has_value() && std::abs(b->first - 120) < 1e-9);
    const auto c{ h.at(15) };
    CHECK(c.has_value() && std::abs(c->first - 150) < 1e-9);
    CHECK(!h.at(15.01).has_value());
    h.record(14, 999, 999);
    const auto d{ h.at(14) };
    CHECK(d.has_value() && std::abs(d->first - 140) < 1e-9);
}
TEST("gaps in the history") {
    PositionHistory h{ 8 };
    h.record(10, 100, 0);
    h.record(15, 150, 50);
    h.record(20, 300, 0);
    const auto a{ h.at(17.5) };
    CHECK(a.has_value() && std::abs(a->first - 225) < 1e-9 && std::abs(a->second - 25) < 1e-9);
    const auto b{ h.at(11) };
    CHECK(b.has_value() && std::abs(b->first - 110) < 1e-9);
}
TEST("limiting the rewind") {
    CHECK_NEAR(rewindTick(1000, 5000, 32), 4968, 1e-9);
    CHECK_NEAR(rewindTick(4990.5, 5000, 32), 4990.5, 1e-9);
    CHECK_NEAR(rewindTick(5005, 5000, 32), 5000, 1e-9);
    CHECK_NEAR(rewindTick(4968, 5000, 32), 4968, 1e-9);
}
TEST("hit tests") {
    CHECK(segmentHitsCircle(0, 0, 1, 0, 100, 50, 3, 5));
    CHECK(!segmentHitsCircle(0, 0, 1, 0, 100, 50, 6, 5));
    CHECK(segmentHitsCircle(0, 0, 1, 0, 100, 50, 5, 5));
    CHECK(!segmentHitsCircle(0, 0, 1, 0, 100, -10, 0, 5));
    CHECK(!segmentHitsCircle(0, 0, 1, 0, 100, 110, 0, 5));
    CHECK(segmentHitsCircle(0, 0, 1, 0, 100, 104, 0, 5));
    CHECK(segmentHitsCircle(0, 0, 2, 0, 100, 50, 3, 5));
    CHECK(segmentHitsCircle(0, 0, 3, 4, 100, 30, 40, 1));
    CHECK(!segmentHitsCircle(0, 0, 0, 0, 100, 1, 0, 5));
    CHECK(segmentHitsCircle(0, 0, 0, 1, 100, 1, 1, 5));
}
TEST("a compensated shot") {
    PositionHistory target{ 64 };
    for (std::int64_t t{ 0 }; t <= 25; ++t) target.record(t, 100.0 + 10.0 * t, 500.0);
    const auto seen{ target.at(rewindTick(20, 25, 32)) };
    CHECK(seen.has_value() && segmentHitsCircle(300, 100, 0, 1, 1000, seen->first, seen->second, 5));
    const auto now{ target.at(25) };
    CHECK(now.has_value() && !segmentHitsCircle(300, 100, 0, 1, 1000, now->first, now->second, 5));
}

